def custom_hash(password):
    import secrets
    salt = secrets.token_bytes(20)
    hashed_password = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return base64.b64encode(hashed_password + salt).decode()

def lab2():
    """Lab 2: Python eval() Code Execution"""
    import ast
    if request.method == "POST":
        try:
            # Safe alternative to eval
            expression = request.form.get("val", "")
            output = ast.literal_eval(expression)
            return render_template("lab2.html", output=str(output))
        except Exception as e:
            return render_template("lab2.html", output=str(e))
    return render_template("lab2.html")

def upload_yaml():
    if "file" not in request.files:
        flash("No file selected")
        return redirect(url_for("lab1"))

    file = request.files["file"]
    if file.filename == "":
        flash("No file selected")
        return redirect(url_for("lab1"))

    if file and allowed_file(file.filename):
        try:
            # Safe YAML loading
            data = yaml.safe_load(file.stream)
            return render_template("result.html", content=data, filename=file.filename)
        except Exception as e:
            flash(f"Error processing file: {str(e)}")
            logger.error(f"Error processing YAML file {file.filename}: {str(e)}")
            return redirect(url_for("lab1"))

    flash("Invalid file type")
    return redirect(url_for("lab1"))

def lab():
    """Lab page with the vulnerable login form"""
    if request.method == "POST":
        username = request.form.get("username", "")
        password = request.form.get("password", "")

        # Safe SQL query construction using parameterized queries
        conn = sqlite3.connect("database.db")
        c = conn.cursor()
        result = c.execute(
            "SELECT * FROM users WHERE username=? AND password=?", 
            (username, password)
        ).fetchone()
        conn.close()

        if result:
            return render_template("lab.html", logged_in_user=result[0])
        else:
            return render_template(
                "lab.html",
                error="Invalid username or password"
            )
    return render_template("lab.html")

